import * as T from './vendor/three.module.js';
import {FURNITURE,FURNITURE_ITEMS,FURNITURE_CATEGORIES} from './furniture-catalogue.js';
import {buyFurniture,placeFurniture,storeFurniture,validatePlacement,furnitureFootprint} from './decor-state.js';
import {makeFurniture,disposeFurniture,attachDecor} from './furniture-meshes.js';
import {buildInterior} from './interior.js';
const money=n=>'₦'+n.toLocaleString();
export function createDecorUI({container,state,onChange,makeRenderer=options=>new T.WebGLRenderer(options)}){
 let tab='owned',category='Tables',selected=null,draft=null,ghost=null,outline=null,confirmation=false,order='',zoom=15,disposed=false;
 container.classList.add('catalogue-sheet','decorator-sheet');container.insertAdjacentHTML('beforeend','<div class="catalogue-heading"><div><span class="eyebrow">AT HOME</span><h2>Make room for you.</h2></div><strong id="decor-wallet"></strong></div><div class="wardrobe-layout"><section class="wardrobe-preview"><div id="decor-stage" class="decor-stage" aria-label="Apartment furniture placement preview"></div><p class="preview-caption-static">Tap the floor to position. Moves stay a preview until you Place. Installed bed, cooker, bathroom, desk, wardrobe and sofa stay available.</p><label class="catalogue-slider">Room zoom<input id="decor-zoom" type="range" min="9" max="20" step=".2" value="15"></label><div class="placement-controls"><button id="decor-up" aria-label="Move toward back wall">↑</button><button id="decor-left" aria-label="Move left">←</button><button id="decor-rotate">Rotate 90°</button><button id="decor-right" aria-label="Move right">→</button><button id="decor-down" aria-label="Move toward entrance">↓</button></div><p id="decor-status" role="status" aria-live="polite"></p><div id="decor-selection"></div></section><section class="wardrobe-browser"><div class="catalogue-tabs"><button id="decor-owned">My furniture</button><button id="decor-shop">Shop</button></div><div id="decor-categories" class="catalogue-categories"></div><div id="decor-cards" class="catalogue-cards"></div></section></div>');
 const el=id=>container.querySelector('#'+id),scene=new T.Scene();scene.background=new T.Color('#d7ddd0');scene.add(new T.HemisphereLight('#fff3dc','#6a796c',2));const sun=new T.DirectionalLight('#fff0d5',3);sun.position.set(-4,12,8);scene.add(sun);
 const copy=structuredClone(state),home=buildInterior(state.home,state.furniture,state.homeStyle);home.room.position.set(0,0,0);home.room.visible=true;scene.add(home.room);const layout=attachDecor(home,copy);
 const renderer=makeRenderer({antialias:true});renderer.setPixelRatio(Math.min(globalThis.devicePixelRatio||1,1.25));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;const stage=el('decor-stage');stage.appendChild(renderer.domElement);const camera=new T.PerspectiveCamera(43,1,.1,60),raycaster=new T.Raycaster(),plane=new T.Plane(new T.Vector3(0,1,0),-.17);
 function feedback(text){el('decor-status').textContent=text;}
 function clearGhost(){if(ghost){scene.remove(ghost);disposeFurniture(ghost);ghost=null;}if(outline){scene.remove(outline);outline.geometry.dispose();outline.material.dispose();outline=null;}}
 function updateGhost(){clearGhost();if(!draft)return;const valid=validatePlacement(state,draft);ghost=makeFurniture(draft.item);ghost.position.set(draft.x,FURNITURE[draft.item].flat?.2:.17,draft.z);ghost.rotation.y=draft.turn*Math.PI/2;ghost.traverse(o=>{if(o.isMesh){o.material.transparent=true;o.material.opacity=.8;}});scene.add(ghost);const box=furnitureFootprint(draft);outline=new T.LineSegments(new T.EdgesGeometry(new T.BoxGeometry(box.w,.02,box.d)),new T.LineBasicMaterial({color:valid.ok?'#257047':'#c94238'}));outline.position.set(draft.x,.2,draft.z);scene.add(outline);for(const child of layout.layer.children)child.visible=child.userData.instanceId!==draft.id;feedback((valid.ok?'Valid · ':'Invalid · ')+valid.message);const button=el('decor-place');if(button)button.disabled=!valid.ok;}
 function select(item,instance){selected=item;confirmation=false;order='decor-'+crypto.randomUUID();draft=instance?{...instance}:{id:'preview',item,x:1.3,z:.1,turn:0,placed:true};render();updateGhost();}
 function refresh(){copy.decor=structuredClone(state.decor);layout.refresh();onChange();}
 function cancel(){selected=null;draft=null;confirmation=false;clearGhost();for(const child of layout.layer.children)child.visible=true;render();feedback('Preview cancelled. Your saved layout is unchanged.');}
 function render(){el('decor-wallet').textContent=money(state.money);el('decor-owned').setAttribute('aria-pressed',String(tab==='owned'));el('decor-shop').setAttribute('aria-pressed',String(tab==='shop'));el('decor-categories').innerHTML=FURNITURE_CATEGORIES.map((c,i)=>'<button id="decor-category-'+i+'" class="'+(category===c?'selected':'')+'">'+c+'</button>').join('');for(const [i,c] of FURNITURE_CATEGORIES.entries())el('decor-category-'+i).onclick=()=>{category=c;cancel();};
 const entries=tab==='shop'?FURNITURE_ITEMS.filter(i=>i.category===category).map(i=>({item:i})):state.decor.items.filter(i=>FURNITURE[i.item].category===category).map(i=>({item:FURNITURE[i.item],instance:i}));
 el('decor-cards').innerHTML=entries.length?entries.map(({item,instance})=>'<button class="catalogue-card" id="decor-item-'+(instance?.id||item.id)+'"><img loading="lazy" src="assets/catalogue/furniture-'+item.id+'.png" alt="'+item.name+'"><span class="item-name">'+item.name+'</span><span class="item-detail">'+item.detail+'</span><span class="item-price">'+(instance?(instance.placed?'Placed · move or store':'Owned · in storage'):money(item.price))+'</span></button>').join(''):'<p class="catalogue-notice">Your '+category.toLowerCase()+' collection is empty. Browse the shop to find a piece.</p>';
 for(const {item,instance} of entries)el('decor-item-'+(instance?.id||item.id)).onclick=()=>select(item.id,instance);
 const item=FURNITURE[selected],owned=draft&&state.decor.items.some(i=>i.id===draft.id);el('decor-selection').innerHTML=item?'<h3>'+item.name+'</h3><p>'+item.detail+'</p>'+(owned?'<button id="decor-place" class="primary">Place · save position</button><button id="decor-store" class="secondary">Store owned piece</button>':confirmation?'<div class="purchase-confirm"><p>Buy for '+money(item.price)+'? Balance after purchase: '+money(Math.max(0,state.money-item.price))+'.</p><button id="decor-confirm" class="primary">Confirm furniture purchase</button><button id="decor-back" class="secondary">Keep browsing</button></div>':'<button id="decor-buy" class="primary">Buy · '+money(item.price)+'</button>')+'<button id="decor-cancel" class="text-button">Cancel preview</button>':'';
 for(const id of ['up','down','left','right','rotate'])el('decor-'+id).disabled=!draft;
 if(item){el('decor-cancel').onclick=cancel;if(owned){el('decor-place').onclick=()=>{const r=placeFurniture(state,draft.id,draft);if(r.ok){refresh();tab='owned';cancel();}feedback(r.message);};el('decor-store').onclick=()=>{storeFurniture(state,draft.id);refresh();cancel();feedback('Stored. You still own this piece.');};}else if(confirmation){el('decor-back').onclick=()=>{confirmation=false;render();};const purchaseOrder=order;el('decor-confirm').onclick=()=>{const r=buyFurniture(state,item.id,purchaseOrder);if(r.ok){draft={...draft,id:r.id};refresh();confirmation=false;render();updateGhost();}feedback(r.message);};}else el('decor-buy').onclick=()=>{confirmation=true;render();};}
 }
 for(const t of ['owned','shop'])el('decor-'+t).onclick=()=>{tab=t;cancel();};for(const [id,dx,dz] of [['up',0,-.2],['down',0,.2],['left',-.2,0],['right',.2,0]])el('decor-'+id).onclick=()=>{if(draft){draft.x=Math.round((draft.x+dx)*10)/10;draft.z=Math.round((draft.z+dz)*10)/10;updateGhost();}};el('decor-rotate').onclick=()=>{if(draft){draft.turn=(draft.turn+1)%4;updateGhost();}};el('decor-zoom').oninput=()=>zoom=Number(el('decor-zoom').value);
 let pointer=null,down=null;renderer.domElement.addEventListener('pointerdown',e=>{pointer=e.pointerId;down={x:e.clientX,y:e.clientY};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerId!==pointer)return;pointer=null;if(!draft||Math.hypot(e.clientX-down.x,e.clientY-down.y)>15)return;const r=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2),camera);const p=new T.Vector3();if(raycaster.ray.intersectPlane(plane,p)){draft.x=Math.round(p.x*10)/10;draft.z=Math.round(p.z*10)/10;updateGhost();}});for(const type of ['pointercancel','lostpointercapture'])renderer.domElement.addEventListener(type,()=>pointer=null);
 render();return {tick(){if(disposed)return;const w=Math.max(1,stage.clientWidth),h=Math.max(1,stage.clientHeight);if(renderer.domElement.width!==Math.round(w*renderer.getPixelRatio())||renderer.domElement.height!==Math.round(h*renderer.getPixelRatio()))renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();const distance=zoom*Math.max(1,.8/camera.aspect);camera.position.set(distance*.35,distance*.8,distance*.65);camera.lookAt(0,.25,0);renderer.render(scene,camera);},dispose(){disposed=true;clearGhost();disposeFurniture(home.room,{textures:true});renderer.dispose();renderer.forceContextLoss();renderer.domElement.remove();}};
}
